import{z as s,x as p,o as l,c,q as n,j as r,D as o,d as a,s as E,S as d,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"类型推导直觉","description":"","frontmatter":{"title":"类型推导直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/type-inference.md","filePath":"cs/type-inference.md","lastUpdated":1791413859000}'),A={name:"cs/type-inference.md"};function B(h,e,m,u,f,D){const i=p("Mermaid");return l(),c("div",null,[e[2]||(e[2]=n('<h1 id="类型推导直觉" tabindex="-1">类型推导直觉 <a class="header-anchor" href="#类型推导直觉" aria-label="Permalink to &quot;类型推导直觉&quot;">​</a></h1><div class="epigraph"><p>声明可省略类型时，从使用处列出等式，用合一解出最一般类型；检查是推导在注解已写满时的特例。</p><footer>—— 据 Hindley, The Principal Type-Scheme of an Object in Combinatory Logic, 1969；Milner, A Theory of Type Polymorphism in Programming, 1978；龙书第 6 章整理</footer></div><p>上一课<a href="/cs/typecheck">类型检查</a>在声明带着类型、表达式综合再比对的规则下拒绝或放行。本课不重写算术规则。缺口是<strong>注解不全</strong>：<code>let</code> 绑定没有写类型，要从 <code>x+1</code> 与 <code>f(x)</code> 反推 \\(x\\) 的类型。主干只要直觉：类型变量、等式、合一；Hindley–Milner 的 let 多态点名，不把 occurs check 证成论文。后课重载与强制在已解出的类型上再选声明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>检查：已知 \\(e\\) 应有类型 \\(\\tau\\)，递归验证。推导：未知 \\(\\tau\\)，生成 \\(\\tau=\\mathrm{int}\\) 或 \\(\\tau_1\\to\\tau_2\\) 一类约束，解方程组。合一：两个类型表达式最一般的公共实例。失败则类型错误（无限类型、\\(int\\) 与 \\(bool\\) 冲突）。缺口是约束，不是再定义结构等价。</p><p>函数参数：引入新鲜类型变量，体里收集约束，返回类型也是变量或由 <code>return</code> 等式钉死。多态：在 <code>let</code> 处推广未被环境约束的变量，使用处再实例化。这是 Milner 的 let 多态；一等泛型更后，本课不启用。</p><h3 id="推导不是「运行时猜」" tabindex="-1">推导不是「运行时猜」 <a class="header-anchor" href="#推导不是「运行时猜」" aria-label="Permalink to &quot;推导不是「运行时猜」&quot;">​</a></h3><p>仍是编译期。解不出来就拒绝，不生成带 tag 的解释器。动态类型语言不做本课这套等式。</p><p><span class="marginnote">合一就是「解方程」：把两个类型表达式当方程两边，找最一般的一组替换让两边相等；解不出（如 int 与 bool 冲突）或解出无限类型，就报类型错误。编译期完成，与运行时无关。</span></p><p><span class="marginnote">Hindley 1969；Milner 1978（J.CSS）与 Algorithm W。Cardelli 综述可对照上一课。龙书以检查为主，推导作扩展。Appel 的函数式章用合一。本课不把 System F 写进主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>遍历 AST，为无注解节点分配类型变量。对每个运算符发出等式（两操作数合一、结果为规定类型）。<code>Unify</code> 带替换。结束时每个节点得到基类型或带量化的方案。</p>',12)),(l(),r(d,null,{default:o(()=>[E(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AST%5B%22%E9%83%A8%E5%88%86%E6%B3%A8%E8%A7%A3%E7%9A%84%20AST%22%5D%20--%3E%20VAR%5B%22%E7%B1%BB%E5%9E%8B%E5%8F%98%E9%87%8F%22%5D%0A%20%20VAR%20--%3E%20EQ%5B%22%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20EQ%20--%3E%20UNI%5B%22%E5%90%88%E4%B8%80%22%5D%0A%20%20UNI%20--%3E%20TAU%5B%22%E4%B8%BB%E7%B1%BB%E5%9E%8B%20%2F%20%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("p",null,"有注解则当等式的一侧已是具体类型，退化成上一课的检查。",-1)),e[4]||(e[4]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=t("p",null,[a("let 多态回答的是「为什么 "),t("code",null,"id"),a(" 没有被第一个使用者钉死成 "),t("code",null,"int->int"),a("」：")],-1)),(l(),r(d,null,{default:o(()=>[E(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E5%AE%9A%E4%B9%89%20id%20%3D%20fn%20x%20-%3E%20x%22%5D%20--%3E%20ALPHA%5B%22%E4%BD%93%E9%87%8C%E5%8F%AA%E6%9C%89%E7%B1%BB%E5%9E%8B%E5%8F%98%E9%87%8F%20alpha%22%5D%0A%20%20ALPHA%20--%3E%20GEN%5B%22let%20%E5%A4%84%E6%8E%A8%E5%B9%BF%EF%BC%9A%E9%87%8F%E5%8C%96%20alpha%22%5D%0A%20%20GEN%20--%3E%20USE1%5B%22%E4%BD%BF%E7%94%A8%E5%A4%84%E4%B8%80%EF%BC%9Aid%2042%22%5D%0A%20%20GEN%20--%3E%20USE2%5B%22%E4%BD%BF%E7%94%A8%E5%A4%84%E4%BA%8C%EF%BC%9Aid%20true%22%5D%0A%20%20USE1%20--%3E%20I1%5B%22%E5%AE%9E%E4%BE%8B%E5%8C%96%20alpha%20%3A%3D%20int%22%5D%0A%20%20USE2%20--%3E%20I2%5B%22%E5%AE%9E%E4%BE%8B%E5%8C%96%20alpha%20%3A%3D%20bool%22%5D%0A%20%20I1%20--%3E%20OK1%5B%22int%20-%3E%20int%22%5D%0A%20%20I2%20--%3E%20OK2%5B%22bool%20-%3E%20bool%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<p>最一般类型（principal type）使同一 <code>id</code> 的推导结果可被所有合法使用共享。过早实例化会把 <code>id</code> 钉死成 <code>int-&gt;int</code> 而不能用于 <code>bool</code>。let 多态的规则就是为了这个。重载不在合一里：<code>+</code> 有多套规则，下一课先选再合一，或生成有限候选。</p><p>发生检查：变量不能合一到含自身的项，否则无限类型。点名即可。</p><p><span class="marginnote">常见误区：初学者容易以为 \\(\\alpha = \\alpha \\to \\alpha\\) 是合法等式；它意味着一个无穷嵌套的函数（无限类型），任何有限内存都装不下。occurs check 就是在合一前先查变量有没有出现在右侧，查到即拒绝。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 W 伪代码，不做效果系统、生命周期。子类型合一更复杂（宽化），点名留给强制课。后课默认：缺注解可用约束求解；多声明同名或隐式转换是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>推导 = 类型变量 + 合一；检查是约束已写满。</li><li>let 多态在绑定处推广；本课不引入 System F。</li><li>重载与强制不在合一内部解决。</li><li>出处：Hindley, 1969；Milner, 1978；龙书第 6 章。</li></ul>',7))])}const T=s(A,[["render",B]]);export{b as __pageData,T as default};
